# Seurat plotting functions: DimPlot, FeaturePlot, VlnPlot, DotPlot, DoHeatmap, RidgePlot
suppressPackageStartupMessages({library(Seurat); library(ggplot2); library(patchwork)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds")
ggsave("v1_DimPlot.png", DimPlot(so, label = TRUE, repel = TRUE) + NoLegend() + ggtitle("DimPlot: Zeisel cortex/hippocampus"), width = 6, height = 5.5, dpi = 150, bg = "white")
ggsave("v2_FeaturePlot.png", FeaturePlot(so, c("Snap25","Gad1","Aqp4","Mbp"), ncol = 2, order = TRUE), width = 8, height = 7, dpi = 130, bg = "white")
ggsave("v3_VlnPlot.png", VlnPlot(so, c("Gad1","Satb2","Mbp"), pt.size = 0, ncol = 3) & theme(axis.title.x = element_blank()), width = 11, height = 4.5, dpi = 130, bg = "white")
mk <- c("Snap25","Gad1","Gad2","Pvalb","Sst","Satb2","Neurod6","Wfs1","Aqp4","Gfap","Mbp","Plp1","Cx3cr1","C1qa","Cldn5","Flt1","Acta2")
ggsave("v4_DotPlot.png", DotPlot(so, features = mk) + RotatedAxis() + ggtitle("DotPlot of canonical markers"), width = 9, height = 4.5, dpi = 140, bg = "white")
m <- FindAllMarkers(so, only.pos = TRUE, logfc.threshold = 1, min.pct = .3, verbose = FALSE)
top <- unlist(lapply(split(m, m$cluster), function(d) head(d$gene[order(-d$avg_log2FC)], 5)))
so <- ScaleData(so, features = unique(top), verbose = FALSE)
ggsave("v5_DoHeatmap.png", DoHeatmap(subset(so, downsample = 80), features = unique(top), size = 3) + theme(axis.text.y = element_text(size = 6)), width = 9, height = 7, dpi = 130, bg = "white")
ggsave("v6_RidgePlot.png", RidgePlot(so, features = c("Snap25","Plp1"), ncol = 2), width = 10, height = 4.5, dpi = 130, bg = "white")
